scripts.build:
rm -rf dist && mkdir -p dist/server dist/.openai dist/_appgen_meta && cp -R outputs/. dist/ && cp .openai/hosting.json dist/.openai/hosting.json && cat > dist/server/index.js <<'EOF'
export default {
  async fetch(request, env) {
    if (env && env.ASSETS && typeof env.ASSETS.fetch === 'function') {
      return env.ASSETS.fetch(request);
    }
    return new Response('', { status: 204 });
  }
};
EOF
printf '{}\n' > dist/_appgen_meta/appgarden.json
